const VERSION='7.1.0';
const BRAND='Pace & Page';
const SUBJECTS=['物理','生化','生物','化學','英文'];
const SUBJECT_TOTALS={物理:105,生物:177,生化:129,化學:104,英文:0};
const SUBJECT_COLORS={物理:'var(--physics)',生化:'var(--biochem)',生物:'var(--biology)',化學:'var(--chem)',英文:'var(--english)',其他:'var(--blue)'};
const LS={settings:'studyos_v7_settings',cache:'studyos_v7_cache',local:'studyos_v7_local',focus:'studyos_v7_focus',theme:'studyos_theme'};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const pad=n=>String(n).padStart(2,'0');
const now=()=>new Date();
const isoDate=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const startOfDay=d=>new Date(d.getFullYear(),d.getMonth(),d.getDate());
const addDays=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
const startOfWeek=d=>{const x=startOfDay(d);return addDays(x,-((x.getDay()+6)%7))};
const endOfWeek=d=>addDays(startOfWeek(d),6);
const minFmt=m=>{m=Math.max(0,Math.round(Number(m)||0));const h=Math.floor(m/60),r=m%60;return h?`${h}h${r?` ${r}m`:''}`:`${r}m`};
const pct=(a,b)=>b?Math.round(a/b*100):0;
const uid=p=>`${p}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const get=(o,keys,def='')=>{for(const k of keys){if(o&&o[k]!==undefined&&o[k]!==null&&String(o[k])!=='')return o[k]}return def};
const nget=(o,keys)=>Number(get(o,keys,0))||0;
const parseDate=v=>{if(!v)return null;if(v instanceof Date)return v;const s=String(v).trim();let d=new Date(s);if(!isNaN(d))return d;const m=s.match(/(\d{4})[-\/]?(\d{1,2})[-\/]?(\d{1,2})/);return m?new Date(+m[1],+m[2]-1,+m[3]):null};
const sameDay=(a,b)=>isoDate(a)===isoDate(b);

let cloud={activityLog:[],manualProgress:[],quickLog:[],questionLog:[],vocabulary:[],weeklyPlan:[],decisionLog:[],planBoard:[]};
let local=loadJSON(LS.local,{vocabulary:[],weeklyPlan:[],decisionLog:[],planBoard:[],pendingActions:[],templates:[],ui:{studyTab:'courses',insightRange:'week',planMode:'list',courseSubject:'物理'}});
local.vocabulary=local.vocabulary||[];local.weeklyPlan=local.weeklyPlan||[];local.decisionLog=local.decisionLog||[];local.planBoard=local.planBoard||[];local.pendingActions=local.pendingActions||[];local.templates=local.templates||[];local.ui=local.ui||{};
let settings=loadJSON(LS.settings,{apiUrl:'',token:'',examDate:'',reviewReminders:false,reviewStartDate:'',reviewIntervals:[1,3,7,14,30],weekTarget:25,dayCapacity:6});
